using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public sealed class CalculateLoyaltyDiscountAcceptanceTests
{
    private readonly CalculateLoyaltyDiscount _pricing = new();

    private int Charged(LoyaltyTier tier, int subtotalCents) =>
        _pricing.Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier)).TotalCents;

    // S1 Bronze customer is charged the basket less the Bronze reduction
    [Fact]
    public void S1_BronzeBasketIsChargedNinetyFiveHundredCents() =>
        Assert.Equal(9500, Charged(LoyaltyTier.Bronze, 10000));

    // S2 Silver customer is charged the basket less the Silver reduction
    [Fact]
    public void S2_SilverBasketIsChargedNineThousandCents() =>
        Assert.Equal(9000, Charged(LoyaltyTier.Silver, 10000));

    // S3 Gold customer is charged the basket less the Gold reduction
    [Fact]
    public void S3_GoldBasketIsChargedEightyFiveHundredCents() =>
        Assert.Equal(8500, Charged(LoyaltyTier.Gold, 10000));

    // S4 Bronze customer with a tiny basket has the reduction land on a whole cent in their favour
    [Fact]
    public void S4_BronzeTinyBasketIsChargedSevenCents() =>
        Assert.Equal(7, Charged(LoyaltyTier.Bronze, 7));
}

